  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-03-15',
    lines: [
      { sku: 'DEV-HOUR', qty: 5 },
      { sku: 'DES-HOUR', qty: 2 },
    ],
  });

  assert.equal(result.ok, true);
  const totals = invoiceTotals(result.value);

  // DEV-HOUR: 9500 * 5 = 47500, discount 5% = 2375, discounted = 45125, VAT 21% = 9476
  // DES-HOUR: 8500 * 2 = 17000, discount 5% = 850, discounted = 16150, VAT 21% = 3392
  // Subtotal: 64500, Discount: 3225, VAT: 12868, Total: 74143
  assert.equal(totals.subtotal, 64500);
  assert.equal(totals.discount, 3225);
  assert.equal(totals.vat, 12868);
  assert.equal(totals.total, 74143);
});

