});

test('lineDiscount rounds fractional cents correctly', () => {
  const line = { qty: 3, unitPrice: 333, discountPercent: 10 };
  // lineTotal = 3 * 333 = 999
  // discount = 999 * 10 / 100 = 99.9, rounded to 100
  assert.equal(lineDiscount(line), 100);
});

