  assert.equal(lineDiscount(line), 250);
});

test('invoiceTotals includes discount and calculates total', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-03-15',
    lines: [
      { sku: 'DEV-HOUR', qty: 10, discountPercent: 10 }, // 9500*10=95000, discount 9500
    ],
  });

  assert.equal(invoiceResult.ok, true);
  const totals = invoiceTotals(invoiceResult.value);

  // DEV-HOUR is 9500 cents per unit
  // subtotal = 95000
  // discount = 9500 (10%)
  // discounted = 85500
  // vat = 85500 * 21 / 100 = 17955
  // total = 95000 - 9500 + 17955 = 103455
  assert.equal(totals.subtotal, 95000);
  assert.equal(totals.discount, 9500);
  assert.equal(totals.vat, 17955);
  assert.equal(totals.total, 103455);
});

test('invoiceTotals with multiple lines and different discounts', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-03-15',
    lines: [
      { sku: 'DEV-HOUR', qty: 5, discountPercent: 10 }, // 9500*5=47500, discount 4750
      { sku: 'DES-HOUR', qty: 2, discountPercent: 20 }, // 8500*2=17000, discount 3400
    ],
  });

  assert.equal(invoiceResult.ok, true);
  const totals = invoiceTotals(invoiceResult.value);

  // DEV-HOUR: 47500, discount 10% = 4750, discounted = 42750, VAT 21% = 8977.50 → 8978
  // DES-HOUR: 17000, discount 20% = 3400, discounted = 13600, VAT 21% = 2856
  // Total subtotal: 64500, discount: 8150, vat: 11834, total: 68184
  assert.equal(totals.subtotal, 64500);
  assert.equal(totals.discount, 8150);
  assert.equal(totals.vat, 11834);
  assert.equal(totals.total, 68184);
});

test('invoiceTotals clamps total to 0 if discount exceeds subtotal', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2024-03-15',
    status: 'draft',
    lines: [
      {
        sku: 'DEV-HOUR',
        name: 'Development (hour)',
        qty: 1,
        unitPrice: 1000, // 1000 cents = €10
        vatRate: 21,
        discountPercent: 150, // Invalid but we manually create for testing clamping
      },
    ],
  };

  const totals = invoiceTotals(invoice);

  // subtotal = 1000
  // discount = 1000 * 150 / 100 = 1500
  // total = max(0, 1000 - 1500) = 0
  assert.equal(totals.subtotal, 1000);
  assert.equal(totals.discount, 1500);
  assert.equal(totals.total, 0);
});

