test('lineDiscount calculates discount correctly', () => {
  const line = { qty: 10, unitPrice: 1000, discountPercent: 10 };
  // lineTotal = 10 * 1000 = 10000
  // firstDiscount = 10000 * 10 / 100 = 1000
  // afterFirstDiscount = 9000
  // bulkDiscount (qty >= 10) = 9000 * 2.5 / 100 = 225
  // total = 1000 + 225 = 1225
  assert.equal(lineDiscount(line), 1225);
});

test('lineDiscount defaults to 0% discount', () => {
  const line = { qty: 10, unitPrice: 1000 };
  // firstDiscount = 0 (no discountPercent)
  // bulkDiscount (qty >= 10) = 10000 * 2.5 / 100 = 250
  assert.equal(lineDiscount(line), 250);
});

test('lineDiscount rounds fractional cents correctly', () => {
  const line = { qty: 3, unitPrice: 333, discountPercent: 10 };
  // lineTotal = 3 * 333 = 999
  // discount = 999 * 10 / 100 = 99.9, rounded to 100
  assert.equal(lineDiscount(line), 100);
});

test('lineDiscount clamps to 0 if somehow negative', () => {
  const line = { qty: 10, unitPrice: 1000, discountPercent: -10 };
  // This shouldn't happen in normal flow due to validation, but clamping is a safety net
  // firstDiscount = clamped to 0
  // bulkDiscount (qty >= 10) = 10000 * 2.5 / 100 = 250
  assert.equal(lineDiscount(line), 250);
});

test('invoiceTotals includes discount and calculates total', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-03-15',
    lines: [
      { sku: 'DEV-HOUR', qty: 10, discountPercent: 10 }, // 9500*10=95000, discount with bulk
    ],
  });

  assert.equal(invoiceResult.ok, true);
  const totals = invoiceTotals(invoiceResult.value);

  // DEV-HOUR is 9500 cents per unit
  // subtotal = 95000
  // firstDiscount = 95000 * 10 / 100 = 9500
  // afterFirstDiscount = 85500
  // bulkDiscount (qty >= 10) = 85500 * 2.5 / 100 = 2138 (rounded)
  // totalDiscount = 9500 + 2138 = 11638
  // discounted = 95000 - 11638 = 83362
  // vat = 83362 * 21 / 100 = 17506
  // total = 95000 - 11638 + 17506 = 100868
  assert.equal(totals.subtotal, 95000);
  assert.equal(totals.discount, 11638);
  assert.equal(totals.vat, 17506);
  assert.equal(totals.total, 100868);
});

