test('invoiceTotals with discount and VAT', () => {
  // Create invoice with gold tier discount (5%)
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-03-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });

  assert.equal(invoiceResult.ok, true);
  const totals = invoiceTotals(invoiceResult.value);

  // DEV-HOUR: 9500 cents, qty 10 = 95000
  // Discount: 95000 * 5 / 100 = 4750
  // Discounted amount: 95000 - 4750 = 90250
  // VAT: 90250 * 21 / 100 = 18952.50, rounded to 18952 (banker's rounding)
  // Total: 95000 - 4750 + 18952 = 109202
  assert.equal(totals.subtotal, 95000);
  assert.equal(totals.discount, 4750);
  assert.equal(totals.vat, 18952);
  assert.equal(totals.total, 109202);
});

