test('invoiceTotals includes discount and calculates total', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-03-15',
    lines: [
      { sku: 'DEV-HOUR', qty: 10, discountPercent: 10 }, // 9500*10=95000, discount with bulk
    ],
  });

  assert.equal(invoiceResult.ok, true);
  const totals = invoiceTotals(invoiceResult.value);

  // DEV-HOUR is 9500 cents per unit
  // subtotal = 95000
  // firstDiscount = 95000 * 10 / 100 = 9500
  // afterFirstDiscount = 85500
  // bulkDiscount (qty >= 10) = 85500 * 2.5 / 100 = 2138 (rounded)
  // totalDiscount = 9500 + 2138 = 11638
  // discounted = 95000 - 11638 = 83362
  // vat = 83362 * 21 / 100 = 17506
  // total = 95000 - 11638 + 17506 = 100868
  assert.equal(totals.subtotal, 95000);
  assert.equal(totals.discount, 11638);
  assert.equal(totals.vat, 17506);
  assert.equal(totals.total, 100868);
});

