    ],
  });

  assert.equal(invoiceResult.ok, true);
  const totals = invoiceTotals(invoiceResult.value);

  // DEV-HOUR: 47500, discount 10% = 4750, discounted = 42750, VAT 21% = 8977.50 → 8978
  // DES-HOUR: 17000, discount 20% = 3400, discounted = 13600, VAT 21% = 2856
  // Total subtotal: 64500, discount: 8150, vat: 11834, total: 68184
  assert.equal(totals.subtotal, 64500);
  assert.equal(totals.discount, 8150);
  assert.equal(totals.vat, 11834);
  assert.equal(totals.total, 68184);
});

test('invoiceTotals clamps total to 0 if discount exceeds subtotal', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2024-03-15',
    status: 'draft',
    lines: [
      {
        sku: 'DEV-HOUR',
