  // Create invoice with no line discount (standard tier)
  const invoiceResult = createInvoice({
    customerId: 'C-002',
    issueDate: '2024-03-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });

  assert.equal(invoiceResult.ok, true);
  const totals = invoiceTotals(invoiceResult.value);

  // DEV-HOUR: 9500 cents, qty 10 = 95000
  // Discount: bulk discount = 95000 * 2.5 / 100 = 2375 (qty >= 10)
  // Discounted amount: 95000 - 2375 = 92625
  // VAT: 92625 * 21 / 100 = 19451
  // Total: 95000 - 2375 + 19451 = 112076
  assert.equal(totals.subtotal, 95000);
  assert.equal(totals.discount, 2375);
  assert.equal(totals.vat, 19451);
  assert.equal(totals.total, 112076);
});

test('invoiceTotals with discount and VAT', () => {
  // Create invoice with gold tier discount (5%)
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-03-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });

  assert.equal(invoiceResult.ok, true);
  const totals = invoiceTotals(invoiceResult.value);

  // DEV-HOUR: 9500 cents, qty 10 = 95000
  // Tier discount: 95000 * 5 / 100 = 4750
  // After tier discount: 90250
  // Bulk discount (qty >= 10): 90250 * 2.5 / 100 = 2256
  // Total discount: 7006
  // Discounted amount: 95000 - 7006 = 87994
  // VAT: 87994 * 21 / 100 = 18479
  // Total: 95000 - 7006 + 18479 = 106473
  assert.equal(totals.subtotal, 95000);
  assert.equal(totals.discount, 7006);
  assert.equal(totals.vat, 18479);
  assert.equal(totals.total, 106473);
});

