        unitPrice: 1000,
        vatRate: 21,
        discountPercent: 150, // Invalid but for testing clamping
      },
    ],
  };

  const totals = invoiceTotals(invoice);

  // subtotal = 1000
  // discount = 1000 * 150 / 100 = 1500
  // discountedAmount = 1000 - 1500 = -500, clamped to 0
  // vat = 0 * 21 / 100 = 0
  // total = max(0, 1000 - 1500 + 0) = 0
  assert.equal(totals.subtotal, 1000);
  assert.equal(totals.discount, 1500);
  assert.equal(totals.vat, 0);
  assert.equal(totals.total, 0);
});

