    customerId: 'C-002',
    issueDate: '2024-03-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });

  assert.equal(invoiceResult.ok, true);
  const totals = invoiceTotals(invoiceResult.value);

  // DEV-HOUR: 9500 cents, qty 10 = 95000
  // Discount: bulk discount = 95000 * 2.5 / 100 = 2375 (qty >= 10)
  // Discounted amount: 95000 - 2375 = 92625
  // VAT: 92625 * 21 / 100 = 19451
  // Total: 95000 - 2375 + 19451 = 112076
  assert.equal(totals.subtotal, 95000);
  assert.equal(totals.discount, 2375);
  assert.equal(totals.vat, 19451);
  assert.equal(totals.total, 112076);
});

